head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDSTF05501.xml';
scwin.vRowCount = 0;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 기관 데이터를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_SALE_DECL_DTL";
    url += "&queryId=lds.stf.bnsisuchg.select.listSaleDeclDtl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_StdCd);
    url += "&{P}V_BND_INST_CD=" + $c.stf.getObjectValue(cmb_SaleInstCd);
    url += "&{P}V_START_DD=" + $c.stf.getObjectValue(edt_StartDd);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EndDd);
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + $c.stf.getObjectValue(txb_BndListProcsTpCd);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_Update
 * 설명       : 매추일을 수정한다.
 ***********************************************/
scwin.fn_Update = function() {
    if ($c.stf.getObjectValue(edt_SaleDd) == '') {
        $c.win.alert('매출일을 입력하십시오.');
        return;
    }
    if ($c.stf.getObjectValue(edt_SaleDd) >= scwin.vCurDate) {
        var vShowDate = scwin.vCurDate.substring(0, 4) + '.' + scwin.vCurDate.substring(4, 6) + '.' + scwin.vCurDate.substring(6, 8);
        $c.win.alert('매출일을 ' + vShowDate + ' 보다 이전 일자로 입력하십시오.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    var url = "/bns/IsuChgAmt.do?method=updateSaleDeclDtl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var param = "BND_APPL_ID=" + $c.stf.getObjectValue(txb_BndApplNo);
    param += ", BND_LIST_PROCS_TP_CD=" + $c.stf.getObjectValue(txb_BndListProcsTpCd);
    param += ", SALE_DD=" + $c.stf.getObjectValue(edt_SaleDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetCombo
 * 설명       : 콤보데이터를 설정한다.
 ***********************************************/
scwin.fn_SetCombo = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_INFO";
    url += "&queryId=lds.stf.bnscommon.select.listSalesInst";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + $c.stf.getObjectValue(txb_BndListProcsTpCd);
    url += "&{P}V_ISU_CD=" + $c.stf.getObjectValue(txb_StdCd);
    dts_SaleInst.DataID = encodeURI(url);
    dts_SaleInst.reset();
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        fn_GetPar = prt.fn_GetPar;
    }
    if (fn_GetPar != undefined) {
        var arrPar = new Array();
        fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_StdCd, arrPar[0].STD_CD);
        $c.stf.setObjectValue(txb_BndListProcsTpCd, arrPar[0].BND_LIST_PROCS_TP_CD);
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(txb_StdCd, false);
    $c.stf.showObj(txb_BndListProcsTpCd, false);
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Input);
    //파라미터설정
    scwin.fn_SetParam();
    //콤보설정
    scwin.fn_SetCombo();
    //목록조회
    scwin.fn_Search();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_StartDd_onclick = function() {
    popUpCalendar2(edt_StartDd);
};
scwin.img_EndDd_onclick = function() {
    popUpCalendar2(edt_EndDd);
};
scwin.img_SaleDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_SaleDd);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount == 0) return;
    grd_List.Redraw = false;

    //합계추가
    var id = '';
    var vBndTotSalesSum = 0;
    var vRedmptAmtSum = 0;
    var vNetSaleAmtSum = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        //row pos
        if (i == 1) {
            id = dts_List.getCellData(i, 'BND_APPL_ID');
        }

        //일별매출총액
        if (dts_List.getCellData(i, 'BND_TOT_SALES') == '') {
            vBndTotSalesSum += 0;
        } else {
            vBndTotSalesSum += parseInt($c.stf.replaceAll(dts_List.getCellData(i, 'BND_TOT_SALES'), ',', ''));
        }

        //일중중도상환액
        if (dts_List.getCellData(i, 'REDMPT_AMT') == '') {
            vRedmptAmtSum += 0;
        } else {
            vRedmptAmtSum += parseInt($c.stf.replaceAll(dts_List.getCellData(i, 'REDMPT_AMT'), ',', ''));
        }

        //일중중도상환액
        if (dts_List.getCellData(i, 'NET_SALE_AMT') == '') {
            vNetSaleAmtSum += 0;
        } else {
            vNetSaleAmtSum += parseInt($c.stf.replaceAll(dts_List.getCellData(i, 'NET_SALE_AMT'), ',', ''));
        }
    }
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowPosition(), 'BND_APPL_ID', '합계');
    dts_List.setCellData(dts_List.getRowPosition(), 'BND_TOT_SALES', $c.stf.addComma('' + vBndTotSalesSum));
    dts_List.setCellData(dts_List.getRowPosition(), 'REDMPT_AMT', $c.stf.addComma('' + vRedmptAmtSum));
    dts_List.setCellData(dts_List.getRowPosition(), 'NET_SALE_AMT', $c.stf.addComma('' + vNetSaleAmtSum));
    dts_List.setRowPosition($c.cp.getNameValueRow(dts_List, "BND_APPL_ID", id), 0);
    grd_List.Redraw = true;
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        if ("가상장금액" == dts_List.getCellData(row, "BND_APPL_ID")) return;
        if ("합계" == dts_List.getCellData(row, "BND_APPL_ID")) return;
        $c.stf.setObjectValue(txb_BndApplNo, dts_List.getCellData(row, "BND_APPL_ID"));
        $c.stf.setObjectValue(edt_SaleDd, dts_List.getCellData(row, "SALE_DD"));
    }
};
scwin.btn_Update_onclick = function() {
    if (scwin.vRowCount == 0) return;
    if ($c.stf.getObjectValue(txb_BndApplNo) == '') return;
    scwin.fn_Update();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.fn_Search();
};
